    if name == "qg":
        if keys != {"op", "scope", "id", "now"}:
            fail(EXIT_INPUT, "INPUT")
        scope = raw_op["scope"]
        if scope not in ("B", "C", "S"):
            fail(EXIT_INPUT, "INPUT")
        return (
            "qg",
            scope,
            parse_key(raw_op["id"]),
            parse_warm_now(raw_op["now"]),
        )

    if name == "os":
        if keys != {"op", "cap", "q", "ttl"}:
            fail(EXIT_INPUT, "INPUT")
        return (
            "os",
            parse_queue_param(raw_op["cap"]),
            parse_queue_param(raw_op["q"]),
            parse_queue_param(raw_op["ttl"]),
