        )

    if name == "ot":
        if keys != {"op", "now"}:
            fail(EXIT_INPUT, "INPUT")
        return ("ot", parse_now(raw_op["now"]))

    if name == "og":
        if keys != {"op"}:
            fail(EXIT_INPUT, "INPUT")
        return ("og",)

    if name == "oc":
        # 精确键集 op,cid，无 now；cid 沿用非空字符串校验。
        if keys != {"op", "cid"}:
            fail(EXIT_INPUT, "INPUT")
